function retry(fn, attempts) {
  return function(...args) {
    for (let i = 0; i < attempts; i++) {
      try {
        return fn(...args);
      } catch (e) {
        if (i === attempts - 1) throw e;
      }
    }
  };
}
let count = 0;
const unstable = () => {
  count++;
  if (count < 3) throw new Error('Fail');
  return 'Success';
};
